const dns = require("node:dns");
const path = require("node:path");
const { start } = require("./dns_server.cjs");
const mark = (text) => require("fs").appendFileSync(path.join(__dirname, "stage"), `${text}\n`);
const out = {};
const RCODES = { "formerr.test": 1, "servfail.test": 2, "missing.test": 3, "notimp.test": 4, "refused.test": 5 };
const held = [];
const server = await start((query) => {
  if (query.name === "37.2.0.192.in-addr.arpa") return { rcode: 2 };
  if (query.name === "38.2.0.192.in-addr.arpa") return { answers: [["@", "TXT", 60, "wrong type"]] };
  if (query.name in RCODES) return { rcode: RCODES[query.name] };
  if (query.name === "drop.test") return null;
  if (query.name === "garbage.test") return { raw: (q) => Buffer.from([q.id >> 8, q.id & 255, 3]) };
  if (query.name === "wrongid.test") return { raw: (q) => Buffer.concat([Buffer.from([(q.id + 1) >> 8 & 255, (q.id + 1) & 255]), Buffer.from([0x81, 0x80, 0, 1, 0, 0, 0, 0, 0, 0]), q.question]) };
  if (query.name === "held.test") return new Promise((resolve) => held.push(() => resolve({ answers: [["@", "A", 60, "192.0.2.30"]] })));
  if (query.type === "A") return { answers: [["@", "A", 60, "192.0.2.31"]] };
  return { answers: [] };
});
const shape = (error) => [error.name, error.code, error.errno ?? null, "errno" in error, error.syscall, error.hostname, error.message, Object.keys(error)];
const fail = (promise) => promise.then((value) => ["resolved", value], shape);
const thrown = (fn) => {
  try {
    fn();
    return "ok";
  } catch (error) {
    return [error.name, error.code, error.message];
  }
};
const resolver = new dns.promises.Resolver({ timeout: 5000, tries: 1 });
resolver.setServers([server.address]);
const short = new dns.promises.Resolver({ timeout: 300, tries: 1 });
short.setServers([server.address]);
mark("rcodes");
out.reverseServfail = await fail(resolver.reverse("192.0.2.37"));
out.reverseWrongType = await fail(resolver.reverse("192.0.2.38"));
out.nxdomain = await fail(resolver.resolve4("missing.test"));
out.nodata = await fail(resolver.resolveMx("nodata.test"));
out.nodataSoa = await fail(resolver.resolveSoa("nodata.test"));
out.servfail = await fail(resolver.resolve6("servfail.test"));
out.refused = await fail(resolver.resolveTxt("refused.test"));
out.notimp = await fail(resolver.resolveSrv("notimp.test"));
out.formerr = await fail(resolver.resolveNs("formerr.test"));
out.anyMissing = await fail(resolver.resolveAny("missing.test"));
out.tlsaMissing = await fail(resolver.resolveTlsa("missing.test"));
out.caaNoData = await fail(resolver.resolveCaa("nodata.test"));
mark("timeouts");
out.timeout = await fail(short.resolve4("drop.test"));
out.garbage = await fail(resolver.resolve4("garbage.test"));
out.wrongId = await fail(short.resolve4("wrongid.test"));
const twice = new dns.promises.Resolver({ timeout: 200, tries: 2 });
twice.setServers([server.address]);
out.twoTries = await fail(twice.resolveCname("drop.test"));
out.dropQueries = server.queries("drop.test");
mark("callback errors");
const callback = new dns.Resolver({ timeout: 5000, tries: 1 });
callback.setServers([server.address]);
const shortCallback = new dns.Resolver({ timeout: 300, tries: 1 });
shortCallback.setServers([server.address]);
out.cbNxdomain = await new Promise((resolve) => callback.resolveSoa("missing.test", (error, value) => resolve([shape(error), value === undefined])));
out.cbTimeout = await new Promise((resolve) => shortCallback.resolve("drop.test", "PTR", (error) => resolve(shape(error))));
mark("validation");
out.badName = thrown(() => resolver.resolve4(123));
out.badNameCallback = thrown(() => callback.resolve4(123, () => {}));
out.noCallback = thrown(() => callback.resolve4("example.test"));
out.badRrtype = thrown(() => resolver.resolve("example.test", "BOGUS"));
out.rrtypeType = thrown(() => resolver.resolve("example.test", 1));
out.badTimeout = thrown(() => new dns.Resolver({ timeout: 1.5 }));
out.badTries = thrown(() => new dns.Resolver({ tries: 0 }));
out.badOptions = thrown(() => new dns.promises.Resolver("x"));
out.serversType = thrown(() => resolver.setServers("127.0.0.1"));
out.serverEntryType = thrown(() => resolver.setServers([1]));
out.badPort = thrown(() => resolver.setServers(["127.0.0.1:99999"]));
out.badServer = thrown(() => resolver.setServers(["example.test"]));
out.badLocal = thrown(() => resolver.setLocalAddress("nope"));
out.twoV4 = thrown(() => resolver.setLocalAddress("127.0.0.1", "127.0.0.1"));
out.twoV6 = thrown(() => resolver.setLocalAddress("::1", "::1"));
out.localType = thrown(() => resolver.setLocalAddress(1));
out.localOk = thrown(() => resolver.setLocalAddress("127.0.0.1", "::1"));
mark("servers");
const listed = new dns.Resolver();
listed.setServers(["127.0.0.1", "127.0.0.1:5353", "[::1]:5353", "::1", "[2001:db8::1]", "[2001:db8::2]:53", "192.0.2.1:53"]);
out.listed = listed.getServers();
listed.setServers([]);
out.emptied = listed.getServers();
mark("in flight");
const busy = new dns.promises.Resolver({ timeout: 3000, tries: 1 });
busy.setServers([server.address]);
const pending = busy.resolve4("held.test");
await server.waitFor((entry) => entry.name === "held.test");
out.setDuringFlight = thrown(() => busy.setServers(["192.0.2.1"]));
if (Array.isArray(out.setDuringFlight)) out.setDuringFlight[2] = out.setDuringFlight[2].replace(String(server.port), "PORT");
out.serversAfterFailure = busy.getServers().map((entry) => entry.replace(String(server.port), "PORT"));
held.forEach((release) => release());
out.heldResult = await pending;
out.setAfterFlight = thrown(() => busy.setServers([server.address]));
out.afterFlight = await busy.resolve4("after.test");
await server.close();
return out;
